const message = $json.message ?? {};
const chatId = message.chat?.id;
const text = (message.text ?? '').trim().toLowerCase();

if (!chatId) return [];

let reply;
if (text === '/start' || text === 'start' || !text) {
  reply = `👋 Добро пожаловать в FREE RUS VPN!

🆓 Тестовый доступ — 3 дня без оплаты.
💳 Первый месяц — 149 ₽, далее 249 ₽/месяц.
🎁 Пригласите друга: после его первой оплаты вам обоим добавится по 14 дней.

Напишите:
• ТЕСТ — чтобы оставить заявку на тест;
• ТАРИФЫ — чтобы посмотреть условия;
• РЕФЕРАЛ — чтобы узнать про бонус;
• ПОДДЕРЖКА — чтобы связаться с командой.`;
} else if (text === 'тест' || text === 'тест 3 дня') {
  reply = `🆓 Заявка на тестовый доступ принята.

Сейчас бот работает в пилотном режиме: доступ подтверждается оператором. Мы напишем вам в этом чате после проверки наличия свободных мест.`;
} else if (text === 'тарифы' || text === 'тариф') {
  reply = `💳 Тарифы FREE RUS VPN

• Тест: 3 дня — 0 ₽
• Стартовый месяц: 149 ₽
• Далее: 249 ₽/месяц
• Годовой: 1 490 ₽

Перед оплатой вы увидите способ оплаты и окончательные условия.`;
} else if (text === 'реферал' || text === 'рефералы') {
  reply = `🎁 Реферальная программа

После активации доступа бот выдаст персональную ссылку. Когда приглашённый пользователь оплатит первый период, вам обоим добавится по 14 дней.`;
} else if (text === 'поддержка') {
  reply = `💬 Поддержка FREE RUS VPN

Опишите вопрос одним сообщением. В пилотном режиме мы отвечаем вручную в этом чате.`;
} else {
  reply = `Я пока понимаю команды: ТЕСТ, ТАРИФЫ, РЕФЕРАЛ и ПОДДЕРЖКА. Для начала работы отправьте /start.`;
}

return [{ json: { chatId, reply } }];
